<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { useRoute } from "vue-router";
import { useI18n } from "vue-i18n";
import { View } from "@element-plus/icons-vue";
import { systemAPI, type TenantAuditRecord, type TenantSummary } from "@/api/adminSystem";
import { formatBackendTime } from "@/utils/timezone";
const {t}=useI18n(),route=useRoute();
const loading=ref(false),rows=ref<TenantAuditRecord[]>([]),tenants=ref<TenantSummary[]>([]),total=ref(0),page=ref(1),pageSize=ref(20),detailVisible=ref(false),detail=ref<Record<string,unknown>>({});
const query=reactive({tenantID:Number(route.query.tenantID||0),operator:"",action:"",targetType:"",result:""});
async function load(){if(!query.tenantID){rows.value=[];total.value=0;return}loading.value=true;try{const result=await systemAPI.tenants.audit(query.tenantID,{operator:query.operator,action:query.action,targetType:query.targetType,result:query.result,page:page.value,pageSize:pageSize.value});rows.value=result.list||[];total.value=result.total||0}finally{loading.value=false}}
async function show(row:TenantAuditRecord){detail.value=await systemAPI.auditLogs.detail(row.logID);detailVisible.value=true}
onMounted(async()=>{tenants.value=(await systemAPI.tenants.list({page:1,pageSize:500})).list||[];await load()});
</script>
<template><main class="platform-page"><header class="page-heading"><div><p>{{t('portal.platform.tenants')}}</p><h1>{{t('tenantCenter.audit.title')}}</h1><span>{{t('tenantCenter.audit.description')}}</span></div></header><section class="filter-band"><el-form inline><el-form-item :label="t('tenantCenter.fields.tenantName')" required><el-select v-model="query.tenantID" filterable><el-option v-for="item in tenants" :key="item.id" :label="`${item.tenantName} (${item.tenantCode})`" :value="item.id"/></el-select></el-form-item><el-form-item :label="t('tenantCenter.fields.operator')"><el-input v-model="query.operator" clearable/></el-form-item><el-form-item :label="t('tenantCenter.fields.action')"><el-input v-model="query.action" clearable/></el-form-item><el-form-item :label="t('tenantCenter.fields.result')"><el-select v-model="query.result" clearable><el-option label="SUCCESS" value="SUCCESS"/><el-option label="FAILED" value="FAILED"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="page=1;load()">{{t('common.search')}}</el-button></el-form-item></el-form></section><section class="table-band"><el-table :data="rows" v-loading="loading" row-key="logID" empty-text="-"><el-table-column prop="operator" :label="t('tenantCenter.fields.operator')" width="140"/><el-table-column prop="action" :label="t('tenantCenter.fields.action')" min-width="230"/><el-table-column prop="targetType" :label="t('tenantCenter.fields.target')" width="150"><template #default="{row}">{{row.targetType}} #{{row.targetID}}</template></el-table-column><el-table-column prop="result" :label="t('tenantCenter.fields.result')" width="105"><template #default="{row}"><el-tag :type="row.result==='SUCCESS'?'success':'danger'">{{row.result}}</el-tag></template></el-table-column><el-table-column prop="reason" :label="t('tenantCenter.fields.reason')" min-width="180" show-overflow-tooltip/><el-table-column prop="ip" label="IP" width="140"/><el-table-column prop="correlationID" label="Trace ID" min-width="190" show-overflow-tooltip/><el-table-column prop="createdAt" :label="t('common.createdAt')" width="175"><template #default="{row}">{{formatBackendTime(row.createdAt)}}</template></el-table-column><el-table-column fixed="right" :label="t('common.actions')" width="80"><template #default="{row}"><el-tooltip :content="t('common.view')"><el-button circle :icon="View" @click="show(row)"/></el-tooltip></template></el-table-column></el-table><el-pagination v-model:current-page="page" v-model:page-size="pageSize" background layout="total, sizes, prev, pager, next" :total="total" @change="load"/></section><el-dialog v-model="detailVisible" :title="t('tenantCenter.audit.detail')" width="760px"><el-descriptions :column="2" border><el-descriptions-item v-for="(value,key) in (detail.overview as Record<string,unknown>||{})" :key="key" :label="String(key)">{{value??'-'}}</el-descriptions-item></el-descriptions><div class="diff-grid"><section><h3>Before</h3><pre>{{JSON.stringify(detail.beforeState,null,2)}}</pre></section><section><h3>After</h3><pre>{{JSON.stringify(detail.afterState,null,2)}}</pre></section></div></el-dialog></main></template>
<style scoped>.platform-page{display:flex;flex-direction:column;gap:16px}.page-heading p{margin:0 0 4px;color:#337ecc;font-size:12px;font-weight:700;text-transform:uppercase}.page-heading h1{margin:0;font-size:24px;letter-spacing:0}.page-heading span{display:block;margin-top:7px;color:#909399;font-size:13px}.filter-band,.table-band{padding:18px 20px;background:#fff;border:1px solid #e4e7ed;border-radius:4px}.filter-band :deep(.el-form-item){margin-bottom:0}.filter-band :deep(.el-input),.filter-band :deep(.el-select){width:190px}.table-band .el-pagination{justify-content:flex-end;margin-top:16px}.diff-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:16px}.diff-grid section{min-width:0}.diff-grid h3{font-size:14px;letter-spacing:0}.diff-grid pre{max-height:320px;overflow:auto;padding:12px;background:#f5f7fa;border:1px solid #e4e7ed;border-radius:4px;white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:700px){.diff-grid{grid-template-columns:1fr}}</style>
